SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

DROP TABLE IF EXISTS `migrations`;
CREATE TABLE `migrations` (`id` int(11) primary key autoincrement not null, `migration` varchar(255) not null, `batch` int(11) not null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for migrations

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (`id` int(11) primary key autoincrement not null, `name` varchar(255) not null, `email` varchar(255) not null, `email_verified_at` timestamp, `password` varchar(255) not null, `role` varchar(255) check (`role` in ('admin', 'user')) not null default 'user', `avatar` varchar(255), `phone` varchar(255), `birth_date` date, `gender` varchar(255) check (`gender` in ('male', 'female', 'other')), `points` int(11) not null default '0', `status` varchar(255) check (`status` in ('active', 'inactive', 'banned')) not null default 'active', `onboarding_completed` tinyint(1) not null default '0', `remember_token` varchar(255), `created_at` timestamp, `updated_at` timestamp, `deleted_at` timestamp, `address` text) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for users

DROP TABLE IF EXISTS `password_reset_tokens`;
CREATE TABLE `password_reset_tokens` (`email` varchar(255) not null, `token` varchar(255) not null, `created_at` timestamp, primary key (`email`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `sessions`;
CREATE TABLE `sessions` (`id` varchar(255) not null, `user_id` int(11), `ip_address` varchar(255), `user_agent` text, `payload` text not null, `last_activity` int(11) not null, primary key (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for sessions

DROP TABLE IF EXISTS `cache`;
CREATE TABLE `cache` (`key` varchar(255) not null, `value` text not null, `expiration` int(11) not null, primary key (`key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `cache_locks`;
CREATE TABLE `cache_locks` (`key` varchar(255) not null, `owner` varchar(255) not null, `expiration` int(11) not null, primary key (`key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `jobs`;
CREATE TABLE `jobs` (`id` int(11) primary key autoincrement not null, `queue` varchar(255) not null, `payload` text not null, `attempts` int(11) not null, `reserved_at` int(11), `available_at` int(11) not null, `created_at` int(11) not null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `job_batches`;
CREATE TABLE `job_batches` (`id` varchar(255) not null, `name` varchar(255) not null, `total_jobs` int(11) not null, `pending_jobs` int(11) not null, `failed_jobs` int(11) not null, `failed_job_ids` text not null, `options` text, `cancelled_at` int(11), `created_at` int(11) not null, `finished_at` int(11), primary key (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `failed_jobs`;
CREATE TABLE `failed_jobs` (`id` int(11) primary key autoincrement not null, `uuid` varchar(255) not null, `connection` text not null, `queue` text not null, `payload` text not null, `exception` text not null, `failed_at` timestamp not null default CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `skin_types`;
CREATE TABLE `skin_types` (`id` int(11) primary key autoincrement not null, `name` varchar(255) not null, `description` text, `created_at` timestamp, `updated_at` timestamp) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for skin_types

DROP TABLE IF EXISTS `skin_concerns`;
CREATE TABLE `skin_concerns` (`id` int(11) primary key autoincrement not null, `name` varchar(255) not null, `slug` varchar(255) not null, `description` text, `icon` varchar(255), `created_at` timestamp, `updated_at` timestamp) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for skin_concerns

DROP TABLE IF EXISTS `product_categories`;
CREATE TABLE `product_categories` (`id` int(11) primary key autoincrement not null, `name` varchar(255) not null, `slug` varchar(255) not null, `description` text, `created_at` timestamp, `updated_at` timestamp) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for product_categories

DROP TABLE IF EXISTS `achievements`;
CREATE TABLE `achievements` (`id` int(11) primary key autoincrement not null, `name` varchar(255) not null, `description` text, `icon` varchar(255), `requirement_type` varchar(255) not null, `requirement_value` int(11) not null, `reward_points` int(11) not null default '0', `created_at` timestamp, `updated_at` timestamp) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for achievements

DROP TABLE IF EXISTS `user_profiles`;
CREATE TABLE `user_profiles` (`id` int(11) primary key autoincrement not null, `user_id` int(11) not null, `skin_type_id` int(11), `skin_goal` text, `allergies` text, `notes` text, `created_at` timestamp, `updated_at` timestamp, foreign key(`user_id`) references `users`(`id`) on delete cascade, foreign key(`skin_type_id`) references `skin_types`(`id`) on delete set null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for user_profiles

DROP TABLE IF EXISTS `user_skin_concerns`;
CREATE TABLE `user_skin_concerns` (`id` int(11) primary key autoincrement not null, `user_id` int(11) not null, `skin_concern_id` int(11) not null, `severity` varchar(255) check (`severity` in ('mild', 'moderate', 'severe')) not null default 'moderate', `created_at` timestamp, `updated_at` timestamp, foreign key(`user_id`) references `users`(`id`) on delete cascade, foreign key(`skin_concern_id`) references `skin_concerns`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for user_skin_concerns

DROP TABLE IF EXISTS `skin_analyses`;
CREATE TABLE `skin_analyses` (`id` int(11) primary key autoincrement not null, `user_id` int(11) not null, `image_path` varchar(255), `analysis_date` date not null, `overall_score` int(11) not null default '0', `estimated_skin_age` numeric, `skin_type_id` int(11), `summary` text, `notes` text, `created_at` timestamp, `updated_at` timestamp, foreign key(`user_id`) references `users`(`id`) on delete cascade, foreign key(`skin_type_id`) references `skin_types`(`id`) on delete set null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for skin_analyses

DROP TABLE IF EXISTS `skin_analysis_metrics`;
CREATE TABLE `skin_analysis_metrics` (`id` int(11) primary key autoincrement not null, `skin_analysis_id` int(11) not null, `metric_type` varchar(255) not null, `score` int(11) not null default '0', `severity` varchar(255) check (`severity` in ('excellent', 'good', 'moderate', 'poor', 'critical')) not null default 'moderate', `description` text, `created_at` timestamp, `updated_at` timestamp, foreign key(`skin_analysis_id`) references `skin_analyses`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for skin_analysis_metrics

DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (`id` int(11) primary key autoincrement not null, `product_category_id` int(11) not null, `brand` varchar(255) not null, `name` varchar(255) not null, `slug` varchar(255) not null, `description` text, `image` varchar(255), `size` varchar(255), `usage_instruction` text, `status` varchar(255) check (`status` in ('active', 'inactive')) not null default 'active', `created_at` timestamp, `updated_at` timestamp, foreign key(`product_category_id`) references `product_categories`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for products

DROP TABLE IF EXISTS `user_products`;
CREATE TABLE `user_products` (`id` int(11) primary key autoincrement not null, `user_id` int(11) not null, `product_id` int(11) not null, `started_at` date, `expired_at` date, `purchase_date` date, `opened_date` date, `status` varchar(255) check (`status` in ('active', 'finished', 'expired', 'discontinued')) not null default 'active', `notes` text, `created_at` timestamp, `updated_at` timestamp, foreign key(`user_id`) references `users`(`id`) on delete cascade, foreign key(`product_id`) references `products`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for user_products

DROP TABLE IF EXISTS `routines`;
CREATE TABLE `routines` (`id` int(11) primary key autoincrement not null, `user_id` int(11) not null, `name` varchar(255) not null, `routine_type` varchar(255) check (`routine_type` in ('morning', 'night')) not null, `active` tinyint(1) not null default '1', `created_at` timestamp, `updated_at` timestamp, foreign key(`user_id`) references `users`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for routines

DROP TABLE IF EXISTS `routine_items`;
CREATE TABLE `routine_items` (`id` int(11) primary key autoincrement not null, `routine_id` int(11) not null, `user_product_id` int(11), `order_number` int(11) not null default '0', `usage_instruction` text, `created_at` timestamp, `updated_at` timestamp, foreign key(`routine_id`) references `routines`(`id`) on delete cascade, foreign key(`user_product_id`) references `user_products`(`id`) on delete set null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for routine_items

DROP TABLE IF EXISTS `recommendations`;
CREATE TABLE `recommendations` (`id` int(11) primary key autoincrement not null, `user_id` int(11) not null, `skin_analysis_id` int(11), `title` varchar(255) not null, `description` text, `created_at` timestamp, `updated_at` timestamp, foreign key(`user_id`) references `users`(`id`) on delete cascade, foreign key(`skin_analysis_id`) references `skin_analyses`(`id`) on delete set null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for recommendations

DROP TABLE IF EXISTS `recommendation_items`;
CREATE TABLE `recommendation_items` (`id` int(11) primary key autoincrement not null, `recommendation_id` int(11) not null, `product_id` int(11), `routine_type` varchar(255) check (`routine_type` in ('morning', 'night')) not null, `order_number` int(11) not null default '0', `reason` text, `usage_instruction` text, `created_at` timestamp, `updated_at` timestamp, foreign key(`recommendation_id`) references `recommendations`(`id`) on delete cascade, foreign key(`product_id`) references `products`(`id`) on delete set null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for recommendation_items

DROP TABLE IF EXISTS `reminders`;
CREATE TABLE `reminders` (`id` int(11) primary key autoincrement not null, `user_id` int(11) not null, `routine_id` int(11), `user_product_id` int(11), `title` varchar(255) not null, `description` text, `reminder_time` time not null, `repeat_type` varchar(255) check (`repeat_type` in ('daily', 'custom')) not null default 'daily', `active` tinyint(1) not null default '1', `created_at` timestamp, `updated_at` timestamp, foreign key(`user_id`) references `users`(`id`) on delete cascade, foreign key(`routine_id`) references `routines`(`id`) on delete set null, foreign key(`user_product_id`) references `user_products`(`id`) on delete set null) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for reminders

DROP TABLE IF EXISTS `reminder_days`;
CREATE TABLE `reminder_days` (`id` int(11) primary key autoincrement not null, `reminder_id` int(11) not null, `day_of_week` int(11) not null, `created_at` timestamp, `updated_at` timestamp, foreign key(`reminder_id`) references `reminders`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `skin_journals`;
CREATE TABLE `skin_journals` (`id` int(11) primary key autoincrement not null, `user_id` int(11) not null, `journal_date` date not null, `skin_condition` varchar(255), `mood` varchar(255), `notes` text, `photo` varchar(255), `skin_score` int(11), `created_at` timestamp, `updated_at` timestamp, foreign key(`user_id`) references `users`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for skin_journals

DROP TABLE IF EXISTS `journal_concerns`;
CREATE TABLE `journal_concerns` (`id` int(11) primary key autoincrement not null, `skin_journal_id` int(11) not null, `skin_concern_id` int(11) not null, `severity` varchar(255) check (`severity` in ('mild', 'moderate', 'severe')) not null default 'moderate', `created_at` timestamp, `updated_at` timestamp, foreign key(`skin_journal_id`) references `skin_journals`(`id`) on delete cascade, foreign key(`skin_concern_id`) references `skin_concerns`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for journal_concerns

DROP TABLE IF EXISTS `user_achievements`;
CREATE TABLE `user_achievements` (`id` int(11) primary key autoincrement not null, `user_id` int(11) not null, `achievement_id` int(11) not null, `achieved_at` timestamp not null, `created_at` timestamp, `updated_at` timestamp, foreign key(`user_id`) references `users`(`id`) on delete cascade, foreign key(`achievement_id`) references `achievements`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for user_achievements

DROP TABLE IF EXISTS `point_transactions`;
CREATE TABLE `point_transactions` (`id` int(11) primary key autoincrement not null, `user_id` int(11) not null, `type` varchar(255) check (`type` in ('credit', 'debit')) not null, `points` int(11) not null, `description` varchar(255) not null, `reference_type` varchar(255), `reference_id` int(11), `created_at` timestamp, `updated_at` timestamp, foreign key(`user_id`) references `users`(`id`) on delete cascade) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Records for point_transactions

SET FOREIGN_KEY_CHECKS=1;
