INSERT INTO `skin_types` (`id`, `name`, `description`, `created_at`, `updated_at`) VALUES ('1', 'Normal', 'Kulit seimbang, tidak terlalu berminyak atau kering. Pori-pori halus dengan sedikit masalah kulit.', '2026-09-11 05:34:05', '2026-09-11 05:34:05');
