INSERT INTO `skin_types` (`id`, `name`, `description`, `created_at`, `updated_at`) VALUES ('3', 'Oily', 'Kulit cenderung berminyak, terutama di T-zone. Pori-pori tampak besar dan rentan berjerawat.', '2026-09-11 05:34:05', '2026-09-11 05:34:05');
INSERT INTO `skin_types` (`id`, `name`, `description`, `created_at`, `updated_at`) VALUES ('4', 'Combination', 'Kombinasi area berminyak (T-zone) dan kering (pipi). Membutuhkan perawatan yang seimbang.', '2026-09-11 05:34:05', '2026-09-11 05:34:05');
INSERT INTO `skin_types` (`id`, `name`, `description`, `created_at`, `updated_at`) VALUES ('5', 'Sensitive', 'Kulit mudah bereaksi terhadap produk atau lingkungan. Sering mengalami kemerahan atau iritasi.', '2026-09-11 05:34:05', '2026-09-11 05:34:05');
